package javaCodings;

public class Factorial_Ofa_number {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
  int num=5;
  int Fact1=1;
  
  for(int i=1; i<=num; i++) {
	  Fact1*=i;
  }
  System.out.println("Factorial of "+num+ ":"+Fact1);
	}

}
                                                          
